<?php
require_once __DIR__ . '/../inc/db.php';
require_once __DIR__ . '/../inc/asterisk.php';
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$db=spbx_db();$errors=[];$ok='';
function spbx_inbound_install_schema($db){
$db->query("CREATE TABLE IF NOT EXISTS spbx_inbound_routes (id INT AUTO_INCREMENT PRIMARY KEY,route_name VARCHAR(120) NOT NULL,trunk_id INT NULL,trunk_context VARCHAR(120) NOT NULL,did VARCHAR(80) NOT NULL,holiday_enabled TINYINT(1) NOT NULL DEFAULT 1,manual_announcement_1_enabled TINYINT(1) NOT NULL DEFAULT 0,manual_announcement_1_file VARCHAR(255) DEFAULT NULL,manual_announcement_2_enabled TINYINT(1) NOT NULL DEFAULT 0,manual_announcement_2_file VARCHAR(255) DEFAULT NULL,closed_audio VARCHAR(255) NOT NULL DEFAULT '/var/www/html/sounds/closed.mp3',closed_action ENUM('hangup','voicemail') NOT NULL DEFAULT 'hangup',main_mailbox VARCHAR(40) NOT NULL DEFAULT '0',main_mailbox_context VARCHAR(80) NOT NULL DEFAULT 'internal',open_destination_context VARCHAR(80) NOT NULL DEFAULT 'internal',open_destination_exten VARCHAR(80) NOT NULL DEFAULT '0',active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_trunk_context (trunk_context),KEY idx_did (did),KEY idx_active (active)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci");
$db->query("CREATE TABLE IF NOT EXISTS spbx_inbound_time_windows (id INT AUTO_INCREMENT PRIMARY KEY,route_id INT NOT NULL,weekday ENUM('mon','tue','wed','thu','fri','sat','sun') NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,sort_order INT NOT NULL DEFAULT 0,active TINYINT(1) NOT NULL DEFAULT 1,KEY idx_route_weekday (route_id, weekday)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci");}
spbx_inbound_install_schema($db);
function spbx_inbound_add_ext($stmt,$context,$exten,$priority,$app,$appdata='',$comment=''){$stmt->bind_param('ssisss',$context,$exten,$priority,$app,$appdata,$comment);$stmt->execute();}
function spbx_inbound_build_dialplan($db){
$db->query("DELETE FROM extensions WHERE context LIKE 'from\\_%'");
$routes=$db->query("SELECT * FROM spbx_inbound_routes WHERE active=1 ORDER BY id ASC"); if(!$routes)return;
$ins=$db->prepare("INSERT INTO extensions (context,exten,priority,app,appdata,comment) VALUES (?,?,?,?,?,?)"); if(!$ins)return;
while($r=$routes->fetch_assoc()){
 $ctx=(string)$r['trunk_context']; $did=trim((string)$r['did']); $exten=($did!==''&&$did!=='*')?$did:'s';
 spbx_inbound_add_ext($ins,$ctx,$exten,1,'NoOp','ServusPBX inbound '.$r['route_name']);
 spbx_inbound_add_ext($ins,$ctx,$exten,2,'Ringing','2');
 $p=3;
 if((int)$r['manual_announcement_1_enabled']===1 && trim((string)$r['manual_announcement_1_file'])!==''){spbx_inbound_add_ext($ins,$ctx,$exten,$p++,'Answer','');spbx_inbound_add_ext($ins,$ctx,$exten,$p++,'MP3Player',(string)$r['manual_announcement_1_file']);spbx_inbound_add_ext($ins,$ctx,$exten,$p++,'Hangup','');}else{spbx_inbound_add_ext($ins,$ctx,$exten,$p++,'NoOp','manual announcement 1 inactive');}
 if((int)$r['manual_announcement_2_enabled']===1 && trim((string)$r['manual_announcement_2_file'])!==''){spbx_inbound_add_ext($ins,$ctx,$exten,$p++,'Answer','');spbx_inbound_add_ext($ins,$ctx,$exten,$p++,'MP3Player',(string)$r['manual_announcement_2_file']);spbx_inbound_add_ext($ins,$ctx,$exten,$p++,'Hangup','');}else{spbx_inbound_add_ext($ins,$ctx,$exten,$p++,'NoOp','manual announcement 2 inactive');}
 while($p<=7)spbx_inbound_add_ext($ins,$ctx,$exten,$p++,'NoOp','');
 spbx_inbound_add_ext($ins,$ctx,$exten,8,'Set','TODAY=${STRFTIME(${EPOCH},,%Y-%m-%d)}');
 if((int)$r['holiday_enabled']===1){spbx_inbound_add_ext($ins,$ctx,$exten,9,'Set','IS_BANKHOLIDAY=${DB_EXISTS(bankholiday/${TODAY})}');spbx_inbound_add_ext($ins,$ctx,$exten,10,'GotoIf','${IS_BANKHOLIDAY}?'.$ctx.','.$exten.',25:'.$ctx.','.$exten.',11');}else{spbx_inbound_add_ext($ins,$ctx,$exten,9,'NoOp','holiday check disabled');spbx_inbound_add_ext($ins,$ctx,$exten,10,'NoOp','');}
 $tw=$db->prepare("SELECT * FROM spbx_inbound_time_windows WHERE route_id=? AND active=1 ORDER BY sort_order ASC, FIELD(weekday,'mon','tue','wed','thu','fri','sat','sun'), start_time ASC");$rid=(int)$r['id'];$tw->bind_param('i',$rid);$tw->execute();$res=$tw->get_result();$prio=11;
 while($w=$res->fetch_assoc()){if($prio>=25)break;$start=substr((string)$w['start_time'],0,5);$end=substr((string)$w['end_time'],0,5);$day=(string)$w['weekday'];spbx_inbound_add_ext($ins,$ctx,$exten,$prio++,'GotoIfTime',$start.'-'.$end.','.$day.',*,*?'.$r['open_destination_context'].','.$r['open_destination_exten'].',1');}
 while($prio<25)spbx_inbound_add_ext($ins,$ctx,$exten,$prio++,'NoOp','');
 spbx_inbound_add_ext($ins,$ctx,$exten,25,'Answer',''); spbx_inbound_add_ext($ins,$ctx,$exten,26,'MP3Player',(string)$r['closed_audio']);
 if((string)$r['closed_action']==='voicemail'){spbx_inbound_add_ext($ins,$ctx,$exten,27,'VoiceMail',$r['main_mailbox'].'@'.$r['main_mailbox_context'].',u');spbx_inbound_add_ext($ins,$ctx,$exten,28,'Hangup','');}else{spbx_inbound_add_ext($ins,$ctx,$exten,27,'NoOp','');spbx_inbound_add_ext($ins,$ctx,$exten,28,'Hangup','');}
}}
if($_SERVER['REQUEST_METHOD']==='POST'){
$action=$_POST['action']??'';
if($action==='save_route'){
$id=(int)($_POST['id']??0);$routeName=trim((string)($_POST['route_name']??''));$trunkContext=trim((string)($_POST['trunk_context']??''));$did=trim((string)($_POST['did']??'s'));$holidayEnabled=isset($_POST['holiday_enabled'])?1:0;$manual1=isset($_POST['manual_announcement_1_enabled'])?1:0;$manual1File=trim((string)($_POST['manual_announcement_1_file']??''));$manual2=isset($_POST['manual_announcement_2_enabled'])?1:0;$manual2File=trim((string)($_POST['manual_announcement_2_file']??''));$closedAudio=trim((string)($_POST['closed_audio']??'/var/www/html/sounds/closed.mp3'));$closedAction=($_POST['closed_action']??'')==='voicemail'?'voicemail':'hangup';$mainMailbox=trim((string)($_POST['main_mailbox']??'0'));$mainMailboxContext=trim((string)($_POST['main_mailbox_context']??'internal'));$openCtx=trim((string)($_POST['open_destination_context']??'internal'));$openExten=trim((string)($_POST['open_destination_exten']??'0'));$active=isset($_POST['active'])?1:0;
if($routeName==='')$errors[]='Name fehlt.'; if($trunkContext==='')$errors[]='Trunk-Kontext fehlt.'; if($did==='')$did='s'; if($closedAudio==='')$closedAudio='/var/www/html/sounds/closed.mp3'; if($mainMailbox==='')$mainMailbox='0'; if($mainMailboxContext==='')$mainMailboxContext='internal'; if($openCtx==='')$openCtx='internal'; if($openExten==='')$openExten='0';
if(!$errors){
 if($id>0){$stmt=$db->prepare("UPDATE spbx_inbound_routes SET route_name=?,trunk_context=?,did=?,holiday_enabled=?,manual_announcement_1_enabled=?,manual_announcement_1_file=?,manual_announcement_2_enabled=?,manual_announcement_2_file=?,closed_audio=?,closed_action=?,main_mailbox=?,main_mailbox_context=?,open_destination_context=?,open_destination_exten=?,active=? WHERE id=?");$stmt->bind_param('sssisisissssssii',$routeName,$trunkContext,$did,$holidayEnabled,$manual1,$manual1File,$manual2,$manual2File,$closedAudio,$closedAction,$mainMailbox,$mainMailboxContext,$openCtx,$openExten,$active,$id);$stmt->execute();}
 else{$stmt=$db->prepare("INSERT INTO spbx_inbound_routes (route_name,trunk_context,did,holiday_enabled,manual_announcement_1_enabled,manual_announcement_1_file,manual_announcement_2_enabled,manual_announcement_2_file,closed_audio,closed_action,main_mailbox,main_mailbox_context,open_destination_context,open_destination_exten,active) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)");$stmt->bind_param('sssisisissssssi',$routeName,$trunkContext,$did,$holidayEnabled,$manual1,$manual1File,$manual2,$manual2File,$closedAudio,$closedAction,$mainMailbox,$mainMailboxContext,$openCtx,$openExten,$active);$stmt->execute();$id=$db->insert_id;}
 $db->query("DELETE FROM spbx_inbound_time_windows WHERE route_id=".(int)$id);$days=['mon','tue','wed','thu','fri','sat','sun'];$sort=0;foreach($days as $day){$starts=$_POST['tw_start'][$day]??[];$ends=$_POST['tw_end'][$day]??[];foreach($starts as $i=>$start){$start=trim((string)$start);$end=trim((string)($ends[$i]??''));if($start===''||$end==='')continue;$stmt=$db->prepare("INSERT INTO spbx_inbound_time_windows (route_id,weekday,start_time,end_time,sort_order,active) VALUES (?,?,?,?,?,1)");$stmt->bind_param('isssi',$id,$day,$start,$end,$sort);$stmt->execute();$sort++;}}
 spbx_inbound_build_dialplan($db);spbx_ast_cli('dialplan reload');$ok='Route gespeichert und Dialplan neu geladen.';}}
if($action==='delete_route'){$id=(int)($_POST['id']??0);if($id>0){$db->query("DELETE FROM spbx_inbound_routes WHERE id=".$id);spbx_inbound_build_dialplan($db);spbx_ast_cli('dialplan reload');$ok='Route gelöscht.';}}
if($action==='save_holiday'){$date=trim((string)($_POST['holiday_date']??''));$name=trim((string)($_POST['holiday_name']??''));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))$errors[]='Ungültiges Feiertagsdatum.';if($name==='')$name='Feiertag';if(!$errors){spbx_ast_db_put('bankholiday',$date,$name);$ok='Feiertag gespeichert.';}}
if($action==='delete_holiday'){$date=trim((string)($_POST['holiday_date']??''));if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)){spbx_ast_db_del('bankholiday',$date);$ok='Feiertag gelöscht.';}}}
$edit=null;if(isset($_GET['edit'])){$id=(int)$_GET['edit'];$res=$db->query("SELECT * FROM spbx_inbound_routes WHERE id=".$id);$edit=$res?$res->fetch_assoc():null;}if(isset($_GET['new'])){$edit=['id'=>0,'route_name'=>'','trunk_context'=>'','did'=>'s','holiday_enabled'=>1,'manual_announcement_1_enabled'=>0,'manual_announcement_1_file'=>'/var/www/html/sounds/AB.mp3','manual_announcement_2_enabled'=>0,'manual_announcement_2_file'=>'/var/www/html/sounds/AB2.mp3','closed_audio'=>'/var/www/html/sounds/closed.mp3','closed_action'=>'hangup','main_mailbox'=>'0','main_mailbox_context'=>'internal','open_destination_context'=>'internal','open_destination_exten'=>'0','active'=>1];}
$routes=$db->query("SELECT * FROM spbx_inbound_routes ORDER BY id DESC");$trunks=$db->query("SELECT trunk_name,name,endpoint_id,context,main_number FROM spbx_trunks WHERE active=1 ORDER BY trunk_name,name");$holidays=spbx_ast_db_show_family('bankholiday');$windows=[];if($edit&&(int)$edit['id']>0){$rid=(int)$edit['id'];$res=$db->query("SELECT * FROM spbx_inbound_time_windows WHERE route_id=$rid ORDER BY sort_order ASC,id ASC");if($res)while($w=$res->fetch_assoc())$windows[$w['weekday']][]=$w;}$dayLabels=['mon'=>'Montag','tue'=>'Dienstag','wed'=>'Mittwoch','thu'=>'Donnerstag','fri'=>'Freitag','sat'=>'Samstag','sun'=>'Sonntag'];
?><!doctype html><html lang="de"><head><meta charset="utf-8"><title>ServusPBX - Eingehende Routen</title><link rel="stylesheet" href="/css/style.css"><link rel="stylesheet" href="/assets/servuspbx.css"></head><body><?php if(file_exists(__DIR__.'/../inc/sidebar.php'))include __DIR__.'/../inc/sidebar.php';?><main class="spbx-main"><div class="spbx-page"><div class="spbx-card"><div class="spbx-card-head"><div><div class="spbx-card-title"><?php echo $edit?((int)$edit['id']>0?'Eingehende Route bearbeiten':'Eingehende Route anlegen'):'Eingehende Routen';?></div><?php if(!$edit):?><div class="spbx-card-muted"><?php echo $routes?$routes->num_rows:0;?> Einträge vorhanden.</div><?php endif;?></div><?php if(!$edit):?><a class="spbx-button primary" href="inbound_routes.php?new=1">+ Neue Route</a><?php endif;?></div><?php foreach($errors as $e):?><div class="spbx-alert error"><?php echo h($e);?></div><?php endforeach;?><?php if($ok):?><div class="spbx-alert success"><?php echo h($ok);?></div><?php endif;?><?php if($edit):?><form method="post" class="spbx-form"><input type="hidden" name="action" value="save_route"><input type="hidden" name="id" value="<?php echo (int)$edit['id'];?>"><div class="spbx-grid-2"><div class="spbx-field"><label>Name</label><input name="route_name" required value="<?php echo h($edit['route_name']);?>" placeholder="Hauptnummer"></div><div class="spbx-field"><label>Trunk-Kontext</label><select name="trunk_context" required><option value="">Bitte wählen</option><?php if($trunks):while($t=$trunks->fetch_assoc()):$ctx=$t['context'];$label=($t['trunk_name']?:$t['name']?:$t['endpoint_id']).' - '.$ctx;?><option value="<?php echo h($ctx);?>" <?php echo $edit['trunk_context']===$ctx?'selected':'';?>><?php echo h($label);?></option><?php endwhile;endif;?></select></div><div class="spbx-field"><label>DID / Extension im Trunk-Kontext</label><input name="did" value="<?php echo h($edit['did']);?>" placeholder="s oder Rufnummer"></div><div class="spbx-field"><label>Offen-Ziel</label><div style="display:flex;gap:8px;"><input name="open_destination_context" value="<?php echo h($edit['open_destination_context']);?>" placeholder="internal"><input name="open_destination_exten" value="<?php echo h($edit['open_destination_exten']);?>" placeholder="0"></div></div></div><div class="spbx-field"><label><input type="checkbox" name="holiday_enabled" <?php echo (int)$edit['holiday_enabled']===1?'checked':'';?>> Feiertagsschaltung aktiv</label></div><div class="spbx-grid-2"><div class="spbx-field"><label><input type="checkbox" name="manual_announcement_1_enabled" <?php echo (int)$edit['manual_announcement_1_enabled']===1?'checked':'';?>> Manuelle Ansage 1 aktiv</label><input name="manual_announcement_1_file" value="<?php echo h($edit['manual_announcement_1_file']);?>" placeholder="/var/www/html/sounds/AB.mp3"></div><div class="spbx-field"><label><input type="checkbox" name="manual_announcement_2_enabled" <?php echo (int)$edit['manual_announcement_2_enabled']===1?'checked':'';?>> Manuelle Ansage 2 aktiv</label><input name="manual_announcement_2_file" value="<?php echo h($edit['manual_announcement_2_file']);?>" placeholder="/var/www/html/sounds/AB2.mp3"></div></div><div class="spbx-grid-2"><div class="spbx-field"><label>Geschlossen-Ansage</label><input name="closed_audio" value="<?php echo h($edit['closed_audio']);?>" placeholder="/var/www/html/sounds/closed.mp3"></div><div class="spbx-field"><label>Geschlossen-Aktion</label><select name="closed_action"><option value="hangup" <?php echo $edit['closed_action']==='hangup'?'selected':'';?>>Ansage + Auflegen</option><option value="voicemail" <?php echo $edit['closed_action']==='voicemail'?'selected':'';?>>Ansage + Hauptbox + Auflegen</option></select></div><div class="spbx-field"><label>Hauptbox Mailbox</label><input name="main_mailbox" value="<?php echo h($edit['main_mailbox']);?>" placeholder="0"></div><div class="spbx-field"><label>Hauptbox Context</label><input name="main_mailbox_context" value="<?php echo h($edit['main_mailbox_context']);?>" placeholder="internal"></div></div><h3>Öffnungszeiten</h3><?php foreach($dayLabels as $day=>$label):$list=$windows[$day]??[];if(!$list&&(int)$edit['id']===0)$list=[['start_time'=>'06:00:00','end_time'=>'23:59:00'],['start_time'=>'','end_time'=>'']];?><div class="spbx-field"><label><?php echo h($label);?></label><?php for($i=0;$i<3;$i++):$w=$list[$i]??['start_time'=>'','end_time'=>''];?><div style="display:flex;gap:8px;margin-bottom:6px;"><input type="time" name="tw_start[<?php echo $day;?>][]" value="<?php echo h(substr((string)$w['start_time'],0,5));?>"><input type="time" name="tw_end[<?php echo $day;?>][]" value="<?php echo h(substr((string)$w['end_time'],0,5));?>"></div><?php endfor;?></div><?php endforeach;?><div class="spbx-field"><label><input type="checkbox" name="active" <?php echo (int)$edit['active']===1?'checked':'';?>> Aktiv</label></div><div class="spbx-actions"><button class="spbx-button primary" type="submit">Speichern</button><a class="spbx-button" href="inbound_routes.php">Abbrechen</a></div></form><?php else:?><div class="spbx-table-wrap"><table class="spbx-table"><thead><tr><th>Name</th><th>Kontext</th><th>DID</th><th>Offen-Ziel</th><th>Feiertag</th><th>Geschlossen</th><th>Aktiv</th><th></th></tr></thead><tbody><?php if($routes):while($r=$routes->fetch_assoc()):?><tr><td><?php echo h($r['route_name']);?></td><td><?php echo h($r['trunk_context']);?></td><td><?php echo h($r['did']);?></td><td><?php echo h($r['open_destination_context'].','.$r['open_destination_exten'].',1');?></td><td><?php echo (int)$r['holiday_enabled']===1?'aktiv':'aus';?></td><td><?php echo $r['closed_action']==='voicemail'?'Mailbox':'Auflegen';?></td><td><?php echo (int)$r['active']===1?'Ja':'Nein';?></td><td><a class="spbx-button small" href="inbound_routes.php?edit=<?php echo (int)$r['id'];?>">Bearbeiten</a><form method="post" style="display:inline" onsubmit="return confirm('Route löschen?');"><input type="hidden" name="action" value="delete_route"><input type="hidden" name="id" value="<?php echo (int)$r['id'];?>"><button class="spbx-button small danger" type="submit">Löschen</button></form></td></tr><?php endwhile;endif;?></tbody></table></div><?php endif;?></div><div class="spbx-card" style="margin-top:18px;"><div class="spbx-card-head"><div><div class="spbx-card-title">Globale Feiertage</div><div class="spbx-card-muted">Gespeichert in Asterisk AstDB: bankholiday/YYYY-MM-DD</div></div></div><form method="post" class="spbx-form"><input type="hidden" name="action" value="save_holiday"><div class="spbx-grid-2"><div class="spbx-field"><label>Datum</label><input type="date" name="holiday_date" required></div><div class="spbx-field"><label>Name</label><input name="holiday_name" placeholder="Feiertag"></div></div><button class="spbx-button primary" type="submit">Feiertag speichern</button></form><div class="spbx-table-wrap" style="margin-top:12px;"><table class="spbx-table"><thead><tr><th>Datum</th><th>Name</th><th></th></tr></thead><tbody><?php foreach($holidays as $date=>$name):?><tr><td><?php echo h($date);?></td><td><?php echo h($name);?></td><td><form method="post" onsubmit="return confirm('Feiertag löschen?');"><input type="hidden" name="action" value="delete_holiday"><input type="hidden" name="holiday_date" value="<?php echo h($date);?>"><button class="spbx-button small danger" type="submit">Löschen</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div></main></body></html>
